SELECT DISTINCT m.field_id, m.field_creator_id, m.field_create_time, m.field_update_time, m.field_start_time, m.field_end_time, m.field_name, m.field_content, m.field_type FROM sys_calendar_main m LEFT JOIN sys_calendar_persons p ON p.field_calendar_id = m.field_id WHERE (m.field_creator_id = #{userId} OR p.field_person_id = #{userId})
AND m.field_name LIKE CONCAT('%', #{model.fieldName}, '%')
AND m.field_type = #{model.fieldType}
AND p.field_accept = 1
AND p.field_accept = 0
AND p.field_accept IS NULL
AND m.field_start_time >= #{model.fieldStartTimeStart}
AND m.field_start_time <= #{model.fieldStartTimeEnd}
ORDER BY
m.field_start_time m.field_create_time m.field_create_time
ASC DESC
LIMIT #{pages.pageSize} OFFSET #{offset}

SELECT COUNT(DISTINCT m.field_id) FROM sys_calendar_main m LEFT JOIN sys_calendar_persons p ON p.field_calendar_id = m.field_id WHERE (m.field_creator_id = #{userId} OR p.field_person_id = #{userId})
AND m.field_name LIKE CONCAT('%', #{model.fieldName}, '%')
AND m.field_type = #{model.fieldType}
AND p.field_accept = 1
AND p.field_accept = 0
AND p.field_accept IS NULL
AND m.field_start_time >= #{model.fieldStartTimeStart}
AND m.field_start_time <= #{model.fieldStartTimeEnd}

